private fun generateResolvedLightColorScheme(
    primaryColor: Color,
    secondaryColor: Color,
    onColorMode: String
): ColorScheme {
    val onPrimary =
        when (onColorMode) {
            ON_COLOR_MODE_LIGHT -> Color.White
            ON_COLOR_MODE_DARK -> Color.Black
            else -> getResolvedContrastingTextColor(primaryColor)

} catch (e: Exception) {
    AppLogger.e(
        "AppBackgroundLayer",
        "Error loading video background: ${e.message}",
        e
    )
}

if (availableAnims.isNotEmpty()) {
    while (true) {
        delay(Random.nextLong(2000, 8000))
        val randomAnim = availableAnims.random()
        AppLogger.d(TAG, "Animation effect: Playing random animation '$randomAnim'.")
        controller.fadeInAnimation(
            randomAnim,
            layer = RANDOM_ANIMATION_LAYER,
            loop = 1
        )
    }
}

